/* END GENERATED KBD UPPERCASE TABLE */

_Static_assert(CUI_KBD_KEY_MAX_BYTES + CUI_KBD_UPPER_MAX_GROWTH + sizeof("Ctrl+Alt+Shift+Win+") <=
                   CUI_KBD_TEXT_CAPACITY,
               "Kbd text capacity must include uppercase expansion and modifiers");

/* The caller has validated the input and isolated the first UTF-8 scalar.
 * Table keys pack that scalar's UTF-8 bytes in big-endian order. */
static size_t cui_kbd_uppercase_first(const char *key, size_t bytes, char *output) {
    if (bytes == 1) {
        output[0] = key[0] >= 'a' && key[0] <= 'z' ? (char)(key[0] - ('a' - 'A')) : key[0];
        return 1;
    }
    uint32_t packed = 0;
    for (size_t i = 0; i < bytes; ++i)
        packed = (packed << 8) | (unsigned char)key[i];
    size_t lo = 0, hi = sizeof cui_kbd_uppercase_table / sizeof cui_kbd_uppercase_table[0];
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (packed < cui_kbd_uppercase_table[mid].key)
            hi = mid;
        else if (packed > cui_kbd_uppercase_table[mid].key)
            lo = mid + 1;
        else {
            size_t length = cui_kbd_uppercase_table[mid].length;
            memcpy(output, cui_kbd_uppercase_table[mid].upper, length);
            return length;
        }
    }
    memcpy(output, key, bytes);
    return bytes;
}

size_t cui_kbd_format_stroke(cui_kbd_stroke stroke, bool mac, char *output, size_t capacity) {
    if ((stroke.modifiers & ~(CUI_MOD_CTRL | CUI_MOD_ALT | CUI_MOD_SHIFT | CUI_MOD_META)) ||
        !stroke.key.data || !stroke.key.length || stroke.key.length > CUI_KBD_KEY_MAX_BYTES ||
        !cui_text_line_source_valid(
            (cui_text_line_source){.paragraph = stroke.key, .byte_end = stroke.key.length}))
        return SIZE_MAX;
    for (size_t i = 0; i < stroke.key.length; ++i) {
        unsigned char c = (unsigned char)stroke.key.data[i];
        if (c < 32 || c == 127 ||
            (i + 2 < stroke.key.length && c == 0xe2 &&
             (unsigned char)stroke.key.data[i + 1] == 0x80 &&
             (unsigned char)stroke.key.data[i + 2] == 0xa8))
            return SIZE_MAX;
    }
    static const struct {
        const char *key, *normal, *mac;
    } names[] = {{"ctrl", "Ctrl", "⌃"},
                 {"alt", "Alt", "⌥"},
                 {"shift", "Shift", "⇧"},
                 {"cmd", "Win", "⌘"},
                 {"space", "Space", "Space"},
                 {"backspace", "Backspace", "⌫"},
                 {"delete", "Delete", "⌫"},
                 {"escape", "Esc", "⎋"},
                 {"enter", "Enter", "⏎"},
                 {"pagedown", "Page Down", "Page Down"},
                 {"pageup", "Page Up", "Page Up"},
                 {"left", "Left", "←"},
                 {"right", "Right", "→"},
                 {"up", "Up", "↑"},
                 {"down", "Down", "↓"}};
    for (size_t i = 0; i < sizeof names / sizeof names[0]; ++i) {
        if (stroke.key.length == strlen(names[i].key) &&
            !memcmp(stroke.key.data, names[i].key, stroke.key.length)) {
            cui_str label = cui_string(mac ? names[i].mac : names[i].normal);
            return cui_kbd_format(stroke.modifiers, label, mac, output, capacity);
        }
    }
    size_t first_bytes = 1;
    while (first_bytes < stroke.key.length &&
           ((unsigned char)stroke.key.data[first_bytes] & 0xc0) == 0x80)
        ++first_bytes;
    char key[CUI_KBD_KEY_MAX_BYTES + CUI_KBD_UPPER_MAX_GROWTH];
    size_t upper_bytes = cui_kbd_uppercase_first(stroke.key.data, first_bytes, key);
    size_t suffix_bytes = stroke.key.length - first_bytes;
    memcpy(key + upper_bytes, stroke.key.data + first_bytes, suffix_bytes);
    return cui_kbd_format(stroke.modifiers, (cui_str){key, upper_bytes + suffix_bytes}, mac, output,
                          capacity);
}

